// Siphoned: damage and healing from the creature's spells and magical abilities is halved.
const item = workflow?.item;
const props = workflow?.activity?.midiProperties ?? {};
const magical = item?.type === "spell" || item?.system?.properties?.has?.("mgc") || props.magicdam || props.magiceffect;
if (!magical) return {};
const damageItem = workflow?.damageItem;
const details = damageItem?.damageDetail;
if (!details?.length) return {};

// Recalculate the target's HP change from the edited damage, as Midi-QOL does when it builds it.
const recompute = (damageItem, details) => {
  let damage = 0;
  let temp = 0;
  let healing = 0;
  for (const d of details) {
    if (d.type === "temphp") temp += d.value ?? 0;
    else if (d.type === "healing") healing += d.value ?? 0;
    else if (!["midi-none", "vitality"].includes(d.type)) damage += d.value ?? 0;
  }
  damage = Math.max(0, damage);
  let total = damage + healing;
  total = total < 0 ? Math.ceil(total) : Math.floor(total);
  damageItem.totalDamage = damage;
  if (typeof damageItem.appliedDamage === "number") damageItem.appliedDamage = damage;
  damageItem.healingAdjustedTotalDamage = total;
  const hp = fromUuidSync(damageItem.actorUuid ?? "")?.system?.attributes?.hp;
  if (!hp) return;
  const oldTemp = hp.temp ?? 0;
  const deltaTemp = total > 0 ? Math.min(oldTemp, total) : 0;
  const deltaHP = Math.clamp(total - deltaTemp, -(hp.damage ?? 0), hp.value);
  const newTemp = Math.floor(Math.max(0, oldTemp - deltaTemp, temp));
  damageItem.hpDamage = deltaHP;
  damageItem.newHP = hp.value - deltaHP;
  damageItem.newTempHP = newTemp;
  damageItem.tempDamage = oldTemp - newTemp;
};

// Halve toward zero, so healing (stored as negative damage) halves the same way as damage.
const halve = (value) => Math.sign(value) * Math.floor(Math.abs(value) / 2);

let updated = false;
for (const entry of details) {
  if (["temphp", "midi-none"].includes(entry.type)) continue;
  const original = entry.value ?? 0;
  const reduced = halve(original);
  if (reduced === original) continue;
  entry.value = reduced;
  if (typeof entry.damage === "number") entry.damage = reduced;
  updated = true;
}
if (updated) recompute(damageItem, details);
return {};
